use strict;
use warnings;

my @entities = qw(
  Attachment Memo MemoRelation InstanceSetting User UserSetting
  IdentityProvider Inbox Reaction MemoShare UserIdentity
);

my %store_results;
my %storepb_results;
my %family_results;
my %alias_files;

while (my $path = <STDIN>) {
  chomp $path;
  open my $fh, "<", $path or die "$path: $!";
  local $/;
  my $text = <$fh>;
  close $fh;
  my $pkg = $path;
  $pkg =~ s{/[^/]+$}{};

  # detect store import aliases
  if ($text =~ /([A-Za-z0-9_]+)\s+"github.com\/usememos\/memos\/store"/) {
    my $alias = $1;
    $alias_files{$path} = $alias if $alias ne "store";
  }
  if ($text =~ /([A-Za-z0-9_]+)\s+"github.com\/usememos\/memos\/proto\/gen\/store"/) {
    my $alias = $1;
    $alias_files{$path} .= "|storepb=$alias" if $alias ne "storepb";
  }

  for my $e (@entities) {
    if ($text =~ /\bstore\.$e\b/) {
      $store_results{$e}{$pkg} = 1;
    }
    if ($text =~ /\bstorepb\.$e\b/) {
      $storepb_results{$e}{$pkg} = 1;
    }
    # family: store.Entity, store.FindEntity, store.UpdateEntity, store.DeleteEntity, store.Create-related
    if ($text =~ /\bstore\.(?:Find|Update|Delete)?$e\b/) {
      $family_results{$e}{$pkg} = 1;
    }
  }
}

print "=== store.Entity ===\n";
for my $e (sort { keys(%{$store_results{$b}||{}}) <=> keys(%{$store_results{$a}||{}}) } @entities) {
  printf "%-20s %d\n", $e, scalar(keys %{$store_results{$e}||{}});
}

print "\n=== storepb.Entity ===\n";
for my $e (sort { keys(%{$storepb_results{$b}||{}}) <=> keys(%{$storepb_results{$a}||{}}) } @entities) {
  printf "%-20s %d\n", $e, scalar(keys %{$storepb_results{$e}||{}});
  my @pkgs = sort keys %{$storepb_results{$e}||{}};
  for my $p (@pkgs) { print "  $p\n"; }
}

print "\n=== store family (Entity|Find|Update|Delete) ===\n";
for my $e (sort { keys(%{$family_results{$b}||{}}) <=> keys(%{$family_results{$a}||{}}) } @entities) {
  printf "%-20s %d\n", $e, scalar(keys %{$family_results{$e}||{}});
  my @pkgs = sort keys %{$family_results{$e}||{}};
  for my $p (@pkgs) { print "  $p\n"; }
}

print "\n=== aliases ===\n";
for my $p (sort keys %alias_files) { print "$p => $alias_files{$p}\n"; }
'

